#!/usr/bin/env bash
# Builds KR32OS with the KRCompiler toolchain: no kr32 executable is involved.
#
#   KRC=/path/to/krc bash kr32os/build.sh
#
# The guest C is compiled by `krc -c`, every image is linked and flattened by
# `krc image`, and the guest assembly is handed to the same command, which
# assembles a non-object input. The old script drove `kr32 cc`, `kr32 as` and
# `kr32 ld`; those verbs no longer exist, which is why this file exists.
#
# The initrd and the kernel metadata are generated by the two Python helpers in
# kr32os/tools, which the old script used as well, so their format did not change.
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
build="${KR32OS_BUILD_DIR:-$here/build/linux}"
opt="${KR32OS_OPT:--O1}"
bios_base=0xFFFF0000
kernel_base=0x00020000
user_base=0x00400000

if [[ -z "${KRC:-}" ]]; then
    for candidate in \
        "$here/../../krcompiler/build/linux-gcc-debug/host/bin/Debug/krc" \
        "$HOME/krc/bin/krc"; do
        if [[ -x "$candidate" ]]; then
            KRC="$candidate"
            break
        fi
    done
fi
if [[ -z "${KRC:-}" ]] && command -v krc >/dev/null 2>&1; then
    KRC="$(command -v krc)"
fi
if [[ -z "${KRC:-}" || ! -x "$KRC" ]]; then
    echo "krc was not found; set KRC" >&2
    exit 2
fi

mkdir -p "$build"
includes=(-I "$here/../include" -I "$here/include" -I "$here/kernel" -I "$here/libc" -I "$here/user")

compile() {
    "$KRC" -c --target=kr32 "$opt" "${includes[@]}" "$1" -o "$2"
}

image() {
    # image <output> <base> <inputs...>
    local output="$1" base="$2"
    shift 2
    "$KRC" image --target=kr32 "--base=$base" "$@" -o "$output"
}

# --- kernel C sources -------------------------------------------------------
kernel_objects=()
for name in main console fb shell timer traps user memory process syscall gfx input; do
    compile "$here/kernel/$name.c" "$build/kernel_$name.kro"
    kernel_objects+=("$build/kernel_$name.kro")
done

# --- user programs ----------------------------------------------------------
compile "$here/libc/gfx.c" "$build/user_gfx.kro"
user_inputs=("$here/libc/crt0.S" "$here/libc/syscall.S" "$build/user_gfx.kro")
for name in init fault wx gfxdemo gfxcheck shutdown readline; do
    compile "$here/user/$name.c" "$build/user_$name.kro"
    image "$build/$name.bin" "$user_base" --flat \
        "$here/libc/crt0.S" "$build/user_$name.kro" "$here/libc/syscall.S" "$build/user_gfx.kro"
done

# --- initrd -----------------------------------------------------------------
python3 "$here/tools/mkinitrd.py" "$build/initrd.bin" "$build/initrd.s" \
    init="$build/init.bin" fault="$build/fault.bin" wx="$build/wx.bin" \
    gfxdemo="$build/gfxdemo.bin" gfxcheck="$build/gfxcheck.bin" \
    shutdown="$build/shutdown.bin" readline="$build/readline.bin"

# --- bios -------------------------------------------------------------------
image "$build/bios.bin" "$bios_base" --flat --entry=bios_entry --sym="$build/bios.sym" "$here/bios/entry.S"
image "$build/bios.kr32" "$bios_base" --entry=bios_entry "$here/bios/entry.S"

# --- kernel -----------------------------------------------------------------
kernel_inputs=(
    "$here/boot/entry.S"
    "${kernel_objects[@]}"
    "$here/kernel/traps-asm.S"
    "$here/kernel/fast.S"
    "$here/kernel/user-asm.S"
    "$build/initrd.s"
)
image "$build/kernel.bin" "$kernel_base" --flat --map="$build/kernel.map" --sym="$build/kernel.sym" "${kernel_inputs[@]}"
image "$build/kernel.kr32" "$kernel_base" "${kernel_inputs[@]}"

python3 "$here/tools/mkmeta.py" "$build/kernel.bin" "$build/kernel.map" "$build/kernel.meta"

echo "KR32OS M4 built with the KRCompiler toolchain:"
echo "  $build/bios.bin"
echo "  $build/bios.kr32"
echo "  $build/kernel.bin"
echo "  $build/kernel.kr32"
